// constat:template id=go-check-report version=80 sha256=7ba089fe5133e3b0f82988d9eafabd6850c5c289e93b4e03b5bc3e05a8cdff75
// Generated by DoneMark's onboarding pull request. Turns `go test -json` — the machine-readable
// record `go test` writes natively, with one flag and no plugin — into the per-check report CI
// publishes as the "constat-check-report" (and, on pull requests, "constat-check-report-base")
// workflow artifact. DoneMark's collector downloads that artifact and reads the named checks out
// of it; nothing an agent writes in its own report reaches this file.
//
// Usage: go run .github/scripts/constat-go-report.go <goTestJsonFile> <outputFile> [--expected <headReport>]
//
// The full name of a check is the contract's own: every enclosing block, outermost first, then the
// check's own title, joined with " > ". For Go that is the package's import path, the test
// function, and each subtest under it — `example.com/app/tank > TestTank > refuses_a_negative_reading`.
// The underscores are Go's: `go test` writes a subtest's spaces as underscores and this reporter
// never invents the spaces back, because the name has to be the one Go itself reports.
package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

type event struct {
	Action  string `json:"Action"`
	Package string `json:"Package"`
	Test    string `json:"Test"`
	Output  string `json:"Output"`
}

type check struct {
	Name    string  `json:"name"`
	Status  string  `json:"status"`
	File    *string `json:"file"`
	Picture string  `json:"picture,omitempty"`
	Message string  `json:"message,omitempty"`
	Line    int     `json:"line,omitempty"`
}

type report struct {
	Schema string  `json:"schema"`
	Checks []check `json:"checks"`
}

// The status words the contract names, from the words `go test -json` uses for the same thing.
func statusFor(action string) string {
	switch action {
	case "pass":
		return "passed"
	case "fail":
		return "failed"
	case "skip":
		return "skipped"
	}
	return ""
}

// The picture a check took, if it took one: `.constat/pictures/<slug>.png`, the same slug rule as
// pictureSlug in DoneMark's own code. The file's presence IS the message — nothing has to tell this
// program the name.
func slug(name string) string {
	var out []rune
	dash := false
	for _, r := range strings.ToLower(name) {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') {
			out = append(out, r)
			dash = false
			continue
		}
		if !dash {
			out = append(out, '-')
			dash = true
		}
	}
	trimmed := strings.Trim(string(out), "-")
	if len(trimmed) > 120 {
		trimmed = trimmed[:120]
	}
	return trimmed
}

func pictureFor(repoRoot, name string) string {
	file := slug(name) + ".png"
	if _, err := os.Stat(filepath.Join(repoRoot, ".constat", "pictures", file)); err == nil {
		return file
	}
	return ""
}

// The module this repository is, and the directory its go.mod sits in — what turns a package's
// import path back into a directory on disk, so a check can say which file it is in.
func theModule(from string) (string, string) {
	dir := from
	for {
		body, err := os.ReadFile(filepath.Join(dir, "go.mod"))
		if err == nil {
			for _, line := range strings.Split(string(body), "\n") {
				if strings.HasPrefix(line, "module ") {
					return strings.TrimSpace(strings.TrimPrefix(line, "module ")), dir
				}
			}
			return "", dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", from
		}
		dir = parent
	}
}

var funcLine = regexp.MustCompile(`(?m)^func (Test[A-Za-z0-9_]*)\s*\(`)
var failureLine = regexp.MustCompile(`^\s*([\w./-]+\.go):(\d+): ?(.*)$`)

// Which file each test function of a package is written in, read off the package's own directory.
// `go test -json` never says, and a check with no file has no coverage attributed to it.
func testFiles(repoRoot, moduleDir, modulePath, pkg string) map[string]string {
	found := map[string]string{}
	dir := ""
	switch {
	case modulePath != "" && pkg == modulePath:
		dir = moduleDir
	case modulePath != "" && strings.HasPrefix(pkg, modulePath+"/"):
		dir = filepath.Join(moduleDir, filepath.FromSlash(strings.TrimPrefix(pkg, modulePath+"/")))
	default:
		return found
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return found
	}
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), "_test.go") {
			continue
		}
		body, err := os.ReadFile(filepath.Join(dir, entry.Name()))
		if err != nil {
			continue
		}
		relative, err := filepath.Rel(repoRoot, filepath.Join(dir, entry.Name()))
		if err != nil {
			continue
		}
		for _, match := range funcLine.FindAllStringSubmatch(string(body), -1) {
			found[match[1]] = filepath.ToSlash(relative)
		}
	}
	return found
}

func main() {
	args := os.Args[1:]
	input, output, expected := "", "", ""
	for i := 0; i < len(args); i++ {
		switch {
		case args[i] == "--expected" && i+1 < len(args):
			i++
			expected = args[i]
		case input == "":
			input = args[i]
		case output == "":
			output = args[i]
		}
	}
	if input == "" || output == "" {
		fmt.Fprintln(os.Stderr, "usage: constat-go-report.go <goTestJsonFile> <outputFile> [--expected <headReport>]")
		os.Exit(2)
	}
	repoRoot, err := os.Getwd()
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	modulePath, moduleDir := theModule(repoRoot)

	handle, err := os.Open(input)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s does not exist — refusing to publish an empty check report. Did go test run?\n", input)
		os.Exit(1)
	}
	defer handle.Close()

	type running struct {
		pkg      string
		test     string
		status   string
		message  string
		line     int
		hasChild bool
		order    int
	}
	results := map[string]*running{}
	order := 0
	files := map[string]map[string]string{}

	scanner := bufio.NewScanner(handle)
	scanner.Buffer(make([]byte, 0, 1024*1024), 16*1024*1024)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if !strings.HasPrefix(line, "{") {
			continue
		}
		var e event
		if err := json.Unmarshal([]byte(line), &e); err != nil {
			continue
		}
		if e.Test == "" {
			continue
		}
		key := e.Package + "\x00" + e.Test
		at, seen := results[key]
		if !seen {
			at = &running{pkg: e.Package, test: e.Test, order: order}
			order++
			results[key] = at
			// A test with a subtest is an enclosing block, not a check: the parent's own pass or
			// fail is the subtests' verdict summed up, and publishing it too would put a check on
			// the record that nobody wrote.
			if cut := strings.LastIndex(e.Test, "/"); cut != -1 {
				if parent, ok := results[e.Package+"\x00"+e.Test[:cut]]; ok {
					parent.hasChild = true
				}
			}
		}
		if e.Action == "output" {
			if match := failureLine.FindStringSubmatch(strings.TrimRight(e.Output, "\n")); match != nil && at.message == "" {
				at.message = strings.TrimSpace(match[3])
				fmt.Sscanf(match[2], "%d", &at.line)
			}
			continue
		}
		if status := statusFor(e.Action); status != "" {
			at.status = status
		}
	}

	checks := []check{}
	byOrder := make([]*running, 0, len(results))
	for _, at := range results {
		byOrder = append(byOrder, at)
	}
	for i := 0; i < len(byOrder); i++ {
		for j := i + 1; j < len(byOrder); j++ {
			if byOrder[j].order < byOrder[i].order {
				byOrder[i], byOrder[j] = byOrder[j], byOrder[i]
			}
		}
	}
	for _, at := range byOrder {
		if at.status == "" || at.hasChild {
			continue
		}
		parts := append([]string{at.pkg}, strings.Split(at.test, "/")...)
		name := strings.Join(parts, " > ")
		if _, known := files[at.pkg]; !known {
			files[at.pkg] = testFiles(repoRoot, moduleDir, modulePath, at.pkg)
		}
		var file *string
		if found, ok := files[at.pkg][strings.Split(at.test, "/")[0]]; ok {
			file = &found
		}
		one := check{Name: name, Status: at.status, File: file}
		if expected == "" {
			one.Picture = pictureFor(repoRoot, name)
		}
		if at.status == "failed" {
			one.Message = at.message
			one.Line = at.line
		}
		checks = append(checks, one)
	}

	published := checks
	if expected != "" {
		body, err := os.ReadFile(expected)
		if err != nil {
			fmt.Fprintf(os.Stderr, "expected head report %s does not exist — refusing to publish a before-code report with nothing to compare against.\n", expected)
			os.Exit(1)
		}
		var head report
		if err := json.Unmarshal(body, &head); err != nil {
			fmt.Fprintf(os.Stderr, "head report %s could not be read: %v\n", expected, err)
			os.Exit(1)
		}
		if len(head.Checks) == 0 {
			fmt.Fprintf(os.Stderr, "head report %s names no checks — nothing to compare against.\n", expected)
			os.Exit(1)
		}
		ran := map[string][]check{}
		for _, one := range checks {
			ran[one.Name] = append(ran[one.Name], one)
		}
		published = []check{}
		seen := map[string]bool{}
		for _, one := range head.Checks {
			if seen[one.Name] {
				continue
			}
			seen[one.Name] = true
			if found, ok := ran[one.Name]; ok {
				published = append(published, found...)
				continue
			}
			// Never dropped and never failed: a check that did not even load against the
			// before-code is "did not run", and folding that into a failure would manufacture a
			// claim about the work out of a compile error.
			published = append(published, check{Name: one.Name, Status: "could_not_run", File: nil})
		}
	}

	// Encoded with HTML escaping off: the separator in a check's full name is a greater-than sign,
	// and Go's default encoder would write it as \u003e — still valid JSON, but a name no person
	// reading the artifact could match against their own criterion.
	var encoded bytes.Buffer
	writer := json.NewEncoder(&encoded)
	writer.SetEscapeHTML(false)
	writer.SetIndent("", "  ")
	if err := writer.Encode(report{Schema: "constat.check-report/v1", Checks: published}); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if err := os.MkdirAll(filepath.Dir(output), 0o755); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if err := os.WriteFile(output, encoded.Bytes(), 0o644); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	where := ""
	if expected != "" {
		where = fmt.Sprintf(" (before-code mode, against %s)", expected)
	}
	fmt.Printf("wrote %d check(s) to %s%s\n", len(published), output, where)
}
